//! Minimal readline-style editor for the linear TUI.
//!
//! rustyline can list completions on Tab, but it cannot refresh a menu on every
//! keystroke. Slash commands are a small, deterministic set, so a focused editor
//! gives us the `/i -> /init` menu without pulling a terminal UI framework in.

use std::io::{stdout, IsTerminal, Write};

use crossterm::cursor::{Hide, MoveLeft, MoveRight, MoveToColumn, MoveUp, Show};
use crossterm::event::{
    self, DisableBracketedPaste, EnableBracketedPaste, Event, KeyCode, KeyEventKind, KeyModifiers,
};
use crossterm::execute;
use crossterm::terminal::{self, disable_raw_mode, enable_raw_mode, Clear, ClearType};
use unicode_width::{UnicodeWidthChar, UnicodeWidthStr};

use crate::slash::{CommandRegistry, CommandSpec};
use crate::theme::Theme;

const MAX_MENU_ROWS: usize = 6;
const MENU_NAME_WIDTH: usize = 10;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Input {
    Line(String),
    Interrupted,
    Eof,
}

pub struct LineEditor {
    registry: CommandRegistry,
    history: Vec<String>,
}

impl LineEditor {
    pub fn new(registry: CommandRegistry) -> Self {
        Self {
            registry,
            history: Vec::new(),
        }
    }

    pub fn read_line(
        &mut self,
        raw_prompt: &str,
        styled_prompt: &str,
        theme: Theme,
    ) -> std::io::Result<Input> {
        if !std::io::stdin().is_terminal() || !std::io::stdout().is_terminal() {
            return Err(std::io::Error::other("line editor requires a TTY"));
        }

        let history_index = self.history.len();
        let mut state = State {
            registry: &self.registry,
            history: &mut self.history,
            history_index,
            chars: Vec::new(),
            cursor: 0,
            selected: 0,
            menu_open: false,
            scroll: 0,
            raw_prompt,
            styled_prompt,
            theme,
        };

        enable_raw_mode()?;
        let mut out = stdout();
        execute!(out, EnableBracketedPaste, Hide)?;
        let result = state.run(&mut out);
        let _ = execute!(out, DisableBracketedPaste, Show);
        let _ = disable_raw_mode();
        result
    }
}

struct State<'a> {
    registry: &'a CommandRegistry,
    history: &'a mut Vec<String>,
    history_index: usize,
    chars: Vec<char>,
    cursor: usize,
    selected: usize,
    menu_open: bool,
    scroll: usize,
    raw_prompt: &'a str,
    styled_prompt: &'a str,
    theme: Theme,
}

impl State<'_> {
    fn run(&mut self, out: &mut impl Write) -> std::io::Result<Input> {
        self.refresh_menu();
        self.render(out)?;

        loop {
            match event::read()? {
                Event::Key(key) => {
                    if key.kind == KeyEventKind::Release {
                        continue;
                    }
                    if let Some(input) = self.handle_key(key, out)? {
                        return Ok(input);
                    }
                    self.refresh_menu();
                    self.render(out)?;
                }
                Event::Paste(text) => {
                    let text = text.replace(['\r', '\n'], " ");
                    self.insert(&text);
                    self.refresh_menu();
                    self.render(out)?;
                }
                Event::Resize(_, _) => {
                    self.render(out)?;
                }
                _ => {}
            }
        }
    }

    fn handle_key(
        &mut self,
        key: event::KeyEvent,
        out: &mut impl Write,
    ) -> std::io::Result<Option<Input>> {
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        let alt = key.modifiers.contains(KeyModifiers::ALT);

        if ctrl {
            return match key.code {
                KeyCode::Char('c') => {
                    self.clear_final(out, false)?;
                    Ok(Some(Input::Interrupted))
                }
                KeyCode::Char('d') => {
                    if self.chars.is_empty() {
                        self.clear_final(out, false)?;
                        Ok(Some(Input::Eof))
                    } else {
                        self.delete_at_cursor();
                        Ok(None)
                    }
                }
                KeyCode::Char('j') => self.enter(out),
                KeyCode::Char('a') => {
                    self.cursor = 0;
                    Ok(None)
                }
                KeyCode::Char('e') => {
                    self.cursor = self.chars.len();
                    Ok(None)
                }
                KeyCode::Char('u') => {
                    self.chars.drain(..self.cursor);
                    self.cursor = 0;
                    Ok(None)
                }
                KeyCode::Char('k') => {
                    self.chars.truncate(self.cursor);
                    Ok(None)
                }
                KeyCode::Char('w') => {
                    self.delete_word();
                    Ok(None)
                }
                KeyCode::Char('l') => {
                    execute!(out, Clear(ClearType::All), MoveToColumn(0))?;
                    self.render(out)?;
                    Ok(None)
                }
                _ => Ok(None),
            };
        }

        if alt {
            return match key.code {
                KeyCode::Char('b') => {
                    self.cursor = self.cursor.saturating_sub(1);
                    Ok(None)
                }
                KeyCode::Char('f') => {
                    self.cursor = (self.cursor + 1).min(self.chars.len());
                    Ok(None)
                }
                _ => Ok(None),
            };
        }

        match key.code {
            KeyCode::Enter => self.enter(out),
            KeyCode::Char('\n') => self.enter(out),
            KeyCode::Tab => {
                if self.menu_open {
                    self.accept_selected();
                } else {
                    self.menu_open = !self.candidates().is_empty();
                }
