use std::collections::BTreeMap;
use std::fs;
use std::path::{Path, PathBuf};

use serde::{Deserialize, Serialize};

use crate::AuthError;

#[derive(Debug, Default, Serialize, Deserialize)]
struct Credentials {
    #[serde(default)]
    providers: BTreeMap<String, ProviderEntry>,
}

#[derive(Debug, Serialize, Deserialize)]
struct ProviderEntry {
    api_key: String,
}

pub(crate) struct FileStore {
    path: PathBuf,
}

impl FileStore {
    pub(crate) fn new(path: PathBuf) -> Self {
        Self { path }
    }

    pub(crate) fn path(&self) -> &Path {
        &self.path
    }

    pub(crate) fn get(&self, provider: &str) -> Result<Option<String>, AuthError> {
        let credentials = self.read()?;
        Ok(credentials
            .providers
            .get(provider)
            .map(|entry| entry.api_key.trim().to_string())
            .filter(|key| !key.is_empty()))
    }

    pub(crate) fn set(&self, provider: &str, api_key: &str) -> Result<(), AuthError> {
        let mut credentials = self.read()?;
        credentials.providers.insert(
            provider.to_string(),
            ProviderEntry {
                api_key: api_key.to_string(),
            },
        );
        self.write(&credentials)
    }

    pub(crate) fn remove(&self, provider: &str) -> Result<bool, AuthError> {
        let mut credentials = self.read()?;
        let removed = credentials.providers.remove(provider).is_some();
        if removed {
            self.write(&credentials)?;
        }
        Ok(removed)
    }

    pub(crate) fn is_private(&self) -> bool {
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            self.path
                .metadata()
                .map(|metadata| metadata.permissions().mode() & 0o077 == 0)
                .unwrap_or(true)
        }
        #[cfg(not(unix))]
        {
            true
        }
    }

    fn read(&self) -> Result<Credentials, AuthError> {
        if !self.path.exists() {
            return Ok(Credentials::default());
        }

        let raw = fs::read_to_string(&self.path)?;
        if raw.trim().is_empty() {
            return Ok(Credentials::default());
        }

        toml::from_str(&raw).map_err(|_| AuthError::CorruptCredentials)
    }

    fn write(&self, credentials: &Credentials) -> Result<(), AuthError> {
        let parent = self.path.parent().ok_or(AuthError::NoConfigDir)?;
        let existed = parent.exists();
        fs::create_dir_all(parent)?;

        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            if !existed {
                fs::set_permissions(parent, fs::Permissions::from_mode(0o700))?;
            }
        }

        let data = toml::to_string_pretty(credentials).map_err(|_| AuthError::Serialize)?;
        let temporary = self.path.with_extension("toml.tmp");
        fs::write(&temporary, data)?;

        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            fs::set_permissions(&temporary, fs::Permissions::from_mode(0o600))?;
        }

        fs::rename(&temporary, &self.path)?;

        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            fs::set_permissions(&self.path, fs::Permissions::from_mode(0o600))?;
        }

        Ok(())
    }
}

use keyring::Entry;

const SERVICE: &str = "niucode";

pub(crate) fn get(provider: &str) -> Option<String> {
    let entry = Entry::new(SERVICE, provider).ok()?;
    entry
        .get_password()
        .ok()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
}

pub(crate) fn set(provider: &str, api_key: &str) -> bool {
    Entry::new(SERVICE, provider)
        .and_then(|entry| entry.set_password(api_key))
        .is_ok()
}

pub(crate) fn delete(provider: &str) -> bool {
    Entry::new(SERVICE, provider)
        .and_then(|entry| entry.delete_credential())
        .is_ok()
}

//! Sidecar extension host.
//!
//! A plugin is a local process speaking line-delimited JSON-RPC over stdio.
//! Tools are discovered during `initialize`; calls are serialized per plugin
//! for now (the manifest does not yet declare a concurrency model).

use std::collections::{HashMap, HashSet};
use std::path::{Path, PathBuf};
use std::process::Stdio;
use std::sync::Arc;
use std::time::Duration;

use anyhow::{bail, Context, Result};
use niucode_provider::ToolSpec;
use niucode_tools::ToolResult;
use serde::Deserialize;
use serde_json::{json, Value};
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader, BufWriter};
use tokio::process::{Child, ChildStdin, ChildStdout, Command};
use tokio::sync::Mutex;
use tokio::time::timeout;

const PROTOCOL_VERSION: u64 = 1;
const DEFAULT_TIMEOUT_SECS: u64 = 30;

#[derive(Debug, Clone)]
pub struct MountInfo {
    pub name: String,
    pub version: String,
    pub tools: Vec<String>,
    pub manifest: PathBuf,
}

pub struct MountReport {
    pub host: ExtensionHost,
    pub errors: Vec<String>,
}

/// Discover `.niucode/extensions/*.toml` under the workspace, spawn each
/// sidecar, and register its tools. Reserved tool names (usually built-ins)
/// are rejected rather than shadowed.
pub async fn discover(workspace: &Path, reserved: &[String]) -> MountReport {
    let mut host = ExtensionHost::default();
    let mut errors = Vec::new();
    let mut reserved = reserved.iter().cloned().collect::<HashSet<_>>();

    let directory = workspace.join(".niucode/extensions");
    if !directory.is_dir() {
        return MountReport { host, errors };
    }

    let mut manifests = match std::fs::read_dir(&directory) {
        Ok(entries) => entries
            .filter_map(Result::ok)
            .map(|entry| entry.path())
            .filter(|path| {
                path.extension()
                    .is_some_and(|extension| extension == "toml")
            })
            .collect::<Vec<_>>(),
        Err(error) => {
            errors.push(format!("read {}: {error}", directory.display()));
            return MountReport { host, errors };
        }
    };
    manifests.sort();

    for path in manifests {
        match mount_one(&path, workspace).await {
            Ok((plugin, info)) => {
                let mut collision = None;
                for tool in &info.tools {
                    if !reserved.insert(tool.clone()) {
                        collision = Some(tool.clone());
                        break;
                    }
                }
                if let Some(tool) = collision {
                    errors.push(format!(
                        "{}: tool {tool:?} collides with a built-in or another extension",
                        info.name
                    ));
                    continue;
                }
                host.register(plugin, info);
            }
            Err(error) => errors.push(format!("{}: {error:#}", path.display())),
        }
    }

    MountReport { host, errors }
}

async fn mount_one(path: &Path, workspace: &Path) -> Result<(Plugin, MountInfo)> {
    let text = std::fs::read_to_string(path).with_context(|| format!("read {}", path.display()))?;
    let manifest: Manifest =
        toml::from_str(&text).with_context(|| format!("parse {}", path.display()))?;
    validate_name(&manifest.name)?;
    if manifest.command.trim().is_empty() {
        bail!("manifest command is empty");
    }
    if manifest.protocol != PROTOCOL_VERSION {
        bail!(
            "unsupported extension protocol {} (host supports {PROTOCOL_VERSION})",
            manifest.protocol
        );
    }

    let mut command = Command::new(&manifest.command);
    command
        .args(&manifest.args)
        .current_dir(workspace)
        .env_clear()
        .env("NIUCODE_EXTENSION", "1")
        // Keep only the environment needed to start an interpreter. Never
        // inherit API keys or other credentials from the harness process.
        .env("PATH", std::env::var_os("PATH").unwrap_or_default())
        .env("HOME", workspace)
        .env("PYTHONDONTWRITEBYTECODE", "1")
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::inherit())
        .kill_on_drop(true);
    for key in ["PATHEXT", "SystemRoot", "COMSPEC"] {
        if let Some(value) = std::env::var_os(key) {
            command.env(key, value);
        }
    }
    let mut child = command
        .spawn()
        .with_context(|| format!("spawn extension {}", manifest.name))?;
    let stdin = child.stdin.take().context("extension stdin unavailable")?;
    let stdout = child
        .stdout
        .take()
        .context("extension stdout unavailable")?;

    let mut plugin = Plugin {
        name: manifest.name.clone(),
        child,
        stdin: BufWriter::new(stdin),
        stdout: BufReader::new(stdout),
        next_id: 1,
        timeout: Duration::from_secs(manifest.timeout_secs.max(1)),
        tools: Vec::new(),
    };

    let init = plugin
        .request(
            "initialize",
            json!({
                "protocol": PROTOCOL_VERSION,
                "client": "niucode",
                "cwd": workspace.display().to_string(),
            }),
        )
        .await
        .with_context(|| format!("initialize extension {}", manifest.name))?;

    let version = init
        .get("version")
        .and_then(Value::as_str)
        .unwrap_or("0.0.0")
        .to_string();
    let tools = init
        .get("tools")
        .and_then(Value::as_array)
        .context("initialize result has no tools array")?;

    let mut specs = Vec::new();
    let mut names = Vec::new();
    for tool in tools {
        let name = tool
            .get("name")
            .and_then(Value::as_str)
            .context("extension tool missing name")?;
        validate_tool_name(name)?;
        let description = tool
            .get("description")
            .and_then(Value::as_str)
            .unwrap_or("External extension tool.");
        let schema = tool
            .get("input_schema")
            .cloned()
            .unwrap_or_else(|| json!({"type": "object", "properties": {}}));
        names.push(name.to_string());
        specs.push(ToolSpec::function(name, description, schema));
    }
    if specs.is_empty() {
        bail!("extension {} registered no tools", manifest.name);
    }
    plugin.tools = specs;

    Ok((
        plugin,
        MountInfo {
            name: manifest.name,
            version,
            tools: names,
            manifest: path.to_path_buf(),
